return new[]{"Floor","Wall","WallCap","DoorFrame"}.Select(role=>new {role=role,materials=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(EchoStation.InfiltrationArt.Editor.ArtSampleAssets.PathFor(role)).GetComponentsInChildren<UnityEngine.Renderer>().SelectMany(r=>r.sharedMaterials).Distinct().Select(m=>new {name=m.name,cull=m.HasProperty("_Cull")?m.GetFloat("_Cull"):-1}).ToArray()}).ToArray();
